package config

import (
	"bufio"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

// Config is the complete runtime configuration for vps-watchdog.
//
// The MVP intentionally supports a small YAML subset instead of pulling in a
// YAML dependency. Supported syntax is the simple mapping structure generated by
// configs/config.example.yaml and packaging/install.sh.
type Config struct {
	HostID   string
	Telegram TelegramConfig
	Login    LoginConfig
	Sudo     SudoConfig
	Load     LoadConfig
	Disk     DiskConfig
	Reboot   RebootConfig
	Liveness LivenessConfig
}

type TelegramConfig struct {
	TokenFile  string
	ChatIDFile string
}

type LoginConfig struct {
	Enabled bool
}

type SudoConfig struct {
	Enabled bool
}

type LoadConfig struct {
	Enabled             bool
	SampleIntervalSec   int
	CooldownSec         int
	CPUBusyPercent      float64
	CPUDurationSec      int
	MemAvailablePercent float64
	MemDurationSec      int
	PSIIOSomeAvg60      float64
	IODurationSec       int
}

// DiskConfig controls low disk space alerts (ADR 0010).
type DiskConfig struct {
	Enabled           bool
	Paths             []string
	SampleIntervalSec int
	CooldownSec       int
	DurationSec       int
	FreePercent       float64
	InodesFreePercent float64
}

// RebootConfig controls reboot detection (ADR 0009).
type RebootConfig struct {
	Enabled bool
}

// LivenessConfig controls pings to an external dead man's switch (ADR 0008).
// The ping URL is a secret and lives in its own file.
type LivenessConfig struct {
	Enabled     bool
	PingURLFile string
	IntervalSec int
}

// maxDiskPaths bounds the number of watched mount points.
const maxDiskPaths = 16

// sandboxHiddenPrefixes are replaced for the service by the systemd unit
// (ProtectHome=true, PrivateTmp=true); statfs there would measure a
// placeholder, not the real filesystem.
var sandboxHiddenPrefixes = []string{"/home", "/root", "/run/user", "/tmp", "/var/tmp"}

func Default() Config {
	host, _ := os.Hostname()
	if strings.TrimSpace(host) == "" {
		host = "unknown"
	}
	return Config{
		HostID: host,
		Telegram: TelegramConfig{
			TokenFile:  "/etc/vps-watchdog/telegram.token",
			ChatIDFile: "/etc/vps-watchdog/telegram.chat_id",
		},
		Login: LoginConfig{Enabled: true},
		Sudo:  SudoConfig{Enabled: true},
		Load: LoadConfig{
			Enabled:             true,
			SampleIntervalSec:   15,
			CooldownSec:         900,
			CPUBusyPercent:      90,
			CPUDurationSec:      180,
			MemAvailablePercent: 10,
			MemDurationSec:      180,
			PSIIOSomeAvg60:      20,
			IODurationSec:       180,
		},
		Disk: DiskConfig{
			Enabled:           true,
			Paths:             []string{"/"},
			SampleIntervalSec: 60,
			CooldownSec:       21600,
			DurationSec:       300,
			FreePercent:       10,
			InodesFreePercent: 10,
		},
		Reboot: RebootConfig{Enabled: true},
		Liveness: LivenessConfig{
			Enabled:     false,
			PingURLFile: "/etc/vps-watchdog/liveness.url",
			IntervalSec: 60,
		},
	}
}

func LoadFile(path string) (Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}, fmt.Errorf("read config %s: %w", path, err)
	}
	return Parse(data)
}

func Parse(data []byte) (Config, error) {
	cfg := Default()
	values, err := parseSimpleYAML(data)
	if err != nil {
		return Config{}, err
	}

	for key, raw := range values {
		switch key {
		case "host_id":
			cfg.HostID = parseString(raw)
		case "telegram.token_file":
			cfg.Telegram.TokenFile = parseString(raw)
		case "telegram.chat_id_file":
			cfg.Telegram.ChatIDFile = parseString(raw)
		case "login.enabled":
			cfg.Login.Enabled, err = parseBool(key, raw)
		case "sudo.enabled":
			cfg.Sudo.Enabled, err = parseBool(key, raw)
		case "load.enabled":
			cfg.Load.Enabled, err = parseBool(key, raw)
		case "load.sample_interval_sec":
			cfg.Load.SampleIntervalSec, err = parseInt(key, raw)
		case "load.cooldown_sec":
			cfg.Load.CooldownSec, err = parseInt(key, raw)
		case "load.cpu_busy_percent":
			cfg.Load.CPUBusyPercent, err = parseFloat(key, raw)
		case "load.cpu_duration_sec":
			cfg.Load.CPUDurationSec, err = parseInt(key, raw)
		case "load.mem_available_percent":
			cfg.Load.MemAvailablePercent, err = parseFloat(key, raw)
		case "load.mem_duration_sec":
			cfg.Load.MemDurationSec, err = parseInt(key, raw)
		case "load.psi_io_some_avg60":
			cfg.Load.PSIIOSomeAvg60, err = parseFloat(key, raw)
		case "load.io_duration_sec":
			cfg.Load.IODurationSec, err = parseInt(key, raw)
		case "disk.enabled":
			cfg.Disk.Enabled, err = parseBool(key, raw)
		case "disk.paths":
			cfg.Disk.Paths = parseList(raw)
		case "disk.sample_interval_sec":
			cfg.Disk.SampleIntervalSec, err = parseInt(key, raw)
		case "disk.cooldown_sec":
			cfg.Disk.CooldownSec, err = parseInt(key, raw)
		case "disk.duration_sec":
			cfg.Disk.DurationSec, err = parseInt(key, raw)
		case "disk.free_percent":
			cfg.Disk.FreePercent, err = parseFloat(key, raw)
		case "disk.inodes_free_percent":
			cfg.Disk.InodesFreePercent, err = parseFloat(key, raw)
		case "reboot.enabled":
			cfg.Reboot.Enabled, err = parseBool(key, raw)
		case "liveness.enabled":
			cfg.Liveness.Enabled, err = parseBool(key, raw)
		case "liveness.ping_url_file":
			cfg.Liveness.PingURLFile = parseString(raw)
		case "liveness.interval_sec":
			cfg.Liveness.IntervalSec, err = parseInt(key, raw)
		default:
			return Config{}, fmt.Errorf("unknown config key %q", key)
		}
		if err != nil {
			return Config{}, err
		}
	}

	if err := cfg.Validate(); err != nil {
		return Config{}, err
	}
	return cfg, nil
}

func (c Config) Validate() error {
	var errs []string
	if strings.TrimSpace(c.HostID) == "" {
		errs = append(errs, "host_id must not be empty")
	}
	if strings.TrimSpace(c.Telegram.TokenFile) == "" {
		errs = append(errs, "telegram.token_file must not be empty")
	}
	if strings.TrimSpace(c.Telegram.ChatIDFile) == "" {
		errs = append(errs, "telegram.chat_id_file must not be empty")
	}
	if c.Load.SampleIntervalSec <= 0 {
		errs = append(errs, "load.sample_interval_sec must be > 0")
	}
	if c.Load.CooldownSec < 0 {
		errs = append(errs, "load.cooldown_sec must be >= 0")
	}
	if c.Load.CPUBusyPercent <= 0 || c.Load.CPUBusyPercent > 100 {
		errs = append(errs, "load.cpu_busy_percent must be in (0, 100]")
	}
	if c.Load.CPUDurationSec <= 0 {
		errs = append(errs, "load.cpu_duration_sec must be > 0")
	}
	if c.Load.MemAvailablePercent <= 0 || c.Load.MemAvailablePercent > 100 {
		errs = append(errs, "load.mem_available_percent must be in (0, 100]")
	}
	if c.Load.MemDurationSec <= 0 {
		errs = append(errs, "load.mem_duration_sec must be > 0")
	}
	if c.Load.PSIIOSomeAvg60 < 0 || c.Load.PSIIOSomeAvg60 > 100 {
		errs = append(errs, "load.psi_io_some_avg60 must be in [0, 100]")
	}
	if c.Load.IODurationSec <= 0 {
		errs = append(errs, "load.io_duration_sec must be > 0")
	}
	errs = append(errs, c.Disk.validate()...)
	if c.Liveness.Enabled && strings.TrimSpace(c.Liveness.PingURLFile) == "" {
		errs = append(errs, "liveness.ping_url_file must not be empty when liveness is enabled")
	}
	if c.Liveness.IntervalSec < 10 {
		errs = append(errs, "liveness.interval_sec must be >= 10")
	}
	if len(errs) > 0 {
		return errors.New(strings.Join(errs, "; "))
	}
	return nil
}

func (d DiskConfig) validate() []string {
	var errs []string
	if d.SampleIntervalSec <= 0 {
		errs = append(errs, "disk.sample_interval_sec must be > 0")
	}
	if d.CooldownSec < 0 {
		errs = append(errs, "disk.cooldown_sec must be >= 0")
	}
	if d.DurationSec < 0 {
		errs = append(errs, "disk.duration_sec must be >= 0")
	}
	if d.FreePercent <= 0 || d.FreePercent >= 100 {
		errs = append(errs, "disk.free_percent must be in (0, 100)")
	}
	if d.InodesFreePercent < 0 || d.InodesFreePercent >= 100 {
		errs = append(errs, "disk.inodes_free_percent must be in [0, 100)")
	}
	if d.Enabled && len(d.Paths) == 0 {
		errs = append(errs, "disk.paths must list at least one path when disk is enabled")
	}
	if len(d.Paths) > maxDiskPaths {
		errs = append(errs, fmt.Sprintf("disk.paths must list at most %d paths", maxDiskPaths))
	}
	for _, p := range d.Paths {
		if !strings.HasPrefix(p, "/") {
			errs = append(errs, fmt.Sprintf("disk.paths: %q must be absolute", p))
			continue
		}
		clean := filepath.Clean(p)
		for _, hidden := range sandboxHiddenPrefixes {
			if clean == hidden || strings.HasPrefix(clean, hidden+"/") {
				errs = append(errs, fmt.Sprintf("disk.paths: %q is hidden from the service by the systemd sandbox", p))
			}
		}
	}
	return errs
}

func parseSimpleYAML(data []byte) (map[string]string, error) {
	values := make(map[string]string)
	parents := map[int][]string{}
	scanner := bufio.NewScanner(strings.NewReader(string(data)))
	lineNo := 0

	for scanner.Scan() {
		lineNo++
		line := stripComment(scanner.Text())
		if strings.TrimSpace(line) == "" {
			continue
		}
		indent := countLeadingSpaces(line)
		if indent%2 != 0 {
			return nil, fmt.Errorf("config line %d: indentation must use multiples of two spaces", lineNo)
		}
		trimmed := strings.TrimSpace(line)
		idx := strings.Index(trimmed, ":")
		if idx <= 0 {
			return nil, fmt.Errorf("config line %d: expected key: value", lineNo)
		}
		key := strings.TrimSpace(trimmed[:idx])
		val := strings.TrimSpace(trimmed[idx+1:])
		if key == "" {
			return nil, fmt.Errorf("config line %d: empty key", lineNo)
		}

		var parent []string
		if indent > 0 {
			var ok bool
			parent, ok = parents[indent-2]
			if !ok {
				return nil, fmt.Errorf("config line %d: missing parent for %q", lineNo, key)
			}
		}
		path := append(append([]string{}, parent...), key)
		parents[indent] = path
		for existing := range parents {
			if existing > indent {
				delete(parents, existing)
			}
		}
		if val == "" {
			continue
		}
		values[strings.Join(path, ".")] = val
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return values, nil
}

func stripComment(line string) string {
	inSingle := false
	inDouble := false
	for i, r := range line {
		switch r {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case '#':
			if !inSingle && !inDouble {
				return line[:i]
			}
		}
	}
	return line
}

func countLeadingSpaces(line string) int {
	count := 0
	for _, r := range line {
		if r != ' ' {
			break
		}
		count++
	}
	return count
}

func parseString(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			return s[1 : len(s)-1]
		}
	}
	return s
}

// parseList splits a comma-separated value; the YAML subset has no lists.
func parseList(raw string) []string {
	var out []string
	for _, item := range strings.Split(parseString(raw), ",") {
		if item = strings.TrimSpace(item); item != "" {
			out = append(out, item)
		}
	}
	return out
}

func parseBool(key, raw string) (bool, error) {
	v, err := strconv.ParseBool(parseString(raw))
	if err != nil {
		return false, fmt.Errorf("config %s: expected bool: %w", key, err)
	}
	return v, nil
}

func parseInt(key, raw string) (int, error) {
	v, err := strconv.Atoi(parseString(raw))
	if err != nil {
		return 0, fmt.Errorf("config %s: expected integer: %w", key, err)
	}
	return v, nil
}

func parseFloat(key, raw string) (float64, error) {
	v, err := strconv.ParseFloat(parseString(raw), 64)
	if err != nil {
		return 0, fmt.Errorf("config %s: expected number: %w", key, err)
	}
	return v, nil
}
